SET NAMES utf8mb4;

INSERT IGNORE INTO posts
  (section, slug, status, origin, title, excerpt, tag, coins, level, author, read_minutes, body, meta_description, focus_keyword, tags, featured, published_at, updated_at)
VALUES
('guias', 'defi-sem-susto-rendimentos-e-riscos', 'published', 'manual', 'DeFi sem susto: de onde vêm os rendimentos e quais são os riscos', 'Empréstimos, pools de liquidez e staking: de onde vem o rendimento, quem paga por ele e o que pode dar errado.', NULL, '["ethereum","uniswap"]', 3, 'Redação Vibecoin', 9, '[{"type":"p","text":"DeFi, de finanças descentralizadas, é o conjunto de serviços financeiros que rodam em blockchains sem uma empresa no meio: emprestar, tomar emprestado, trocar moedas e render sobre o que você tem. Em vez de um banco ou uma corretora, quem executa as regras são programas chamados contratos inteligentes. Este guia assume que você já conhece [carteiras e autocustódia](/guias/carteira-fria-quente-e-autocustodia) e [stablecoins](/guias/stablecoins-o-que-sao-e-para-que-servem); se não conhece, comece por eles."},{"type":"h2","text":"Como funciona, na prática"},{"type":"p","text":"Você conecta sua própria carteira a um aplicativo descentralizado e assina transações que movem seus ativos para um contrato inteligente. Esse contrato guarda os fundos e aplica as regras automaticamente. Não há atendimento, conta ou recuperação de senha: tudo depende da sua chave e do código do contrato. A maior parte da atividade acontece no Ethereum e em redes parecidas, e cada operação paga uma taxa de rede (o gás), que pode pesar em valores pequenos."},{"type":"h2","text":"De onde vem o rendimento"},{"type":"p","text":"A pergunta mais importante em DeFi é: quem está pagando esse rendimento? Se você não sabe responder, o rendimento provavelmente vem de um risco que você não está vendo. Existem quatro origens principais."},{"type":"h2","text":"1. Empréstimos"},{"type":"p","text":"Você deposita ativos em um protocolo de empréstimo, e outras pessoas tomam esses ativos emprestados pagando juros, que são repartidos entre quem depositou. Quem toma emprestado precisa deixar um colateral de valor maior do que o empréstimo. Se o preço do colateral cai e a garantia fica abaixo do limite, o contrato liquida a posição automaticamente, vendendo parte do colateral. O rendimento de quem empresta varia com a procura por crédito: não é fixo."},{"type":"h2","text":"2. Pools de liquidez"},{"type":"p","text":"Corretoras descentralizadas, como a [Uniswap](/cotacoes/uniswap), não têm livro de ofertas. Elas usam pools: reservas de dois ativos, abastecidas por usuários chamados provedores de liquidez. Quem negocia paga uma taxa, e uma fração dela vai para os provedores. O rendimento, portanto, é uma fatia das taxas, e depende do volume de negociação."},{"type":"p","text":"O risco específico aqui é a perda impermanente: quando o preço de um dos ativos do par muda muito em relação ao outro, você acaba com mais do ativo que perdeu valor e menos do que valorizou. Em alguns casos, você teria ficado com mais dinheiro se apenas tivesse guardado os dois ativos na carteira. As taxas recebidas podem compensar ou não."},{"type":"h2","text":"3. Staking"},{"type":"p","text":"Em redes de prova de participação, como o Ethereum, quem trava ativos para ajudar a validar blocos recebe recompensas, pagas por novas emissões e por taxas da rede. Existem formas de participar sem operar um validador, como o staking por serviços e o staking líquido, que entrega um token representando o valor travado. O rendimento é variável e há riscos próprios: falha do serviço, punições para validadores que erram (slashing), tempo de espera para sacar e o risco do token que representa o staking perder a paridade com o ativo original."},{"type":"h2","text":"4. Incentivos em tokens (yield farming)"},{"type":"p","text":"Alguns protocolos pagam recompensas extras em um token próprio para atrair usuários. Os percentuais anunciados podem parecer enormes, mas muitas vezes são pagos em um token que perde valor justamente porque está sendo emitido em grande quantidade. Rendimento anunciado em percentual (APY) não é o mesmo que ganho em reais: o que importa é quanto você terá, em valor, quando sair."},{"type":"h2","text":"Os riscos que mais pesam"},{"type":"ul","items":["Falha no contrato inteligente: um erro no código pode ser explorado e esvaziar os fundos. Auditorias reduzem o risco, mas não o eliminam, e já houve ataques a protocolos auditados.","Pontes entre redes (bridges): concentram muito dinheiro e já foram alvo de alguns dos maiores ataques do setor.","Liquidação: em empréstimos, uma queda rápida de preço pode liquidar sua garantia antes que você consiga reagir.","Manipulação de preço (oráculos): contratos dependem de fontes de preço, e atacantes já exploraram essas fontes para drenar protocolos.","Golpes de saída (rug pull): os criadores de um projeto novo retiram o dinheiro dos usuários e somem.","Perda de paridade de stablecoin: se a stablecoin usada no protocolo cai abaixo de 1 dólar, o que parecia seguro deixa de ser.","Aprovações abertas: ao usar um aplicativo, você dá permissão para ele mexer nos seus tokens, e essa permissão pode continuar valendo depois que você sair.","Sem rede de proteção: não há garantia de depósitos nem atendimento que reverta um erro. A transação confirmada não volta."]},{"type":"h2","text":"O sinal de alerta: rendimento alto e garantido"},{"type":"p","text":"Em 2022, a rede Terra oferecia cerca de 20% ao ano em uma stablecoin por meio de um protocolo chamado Anchor. O rendimento era sustentado por subsídios, não por demanda real, e tudo ruiu em maio daquele ano, junto com a stablecoin algorítmica TerraUSD. A regra prática é desconfiar de qualquer retorno muito acima do que o mercado em geral paga, principalmente se for descrito como fixo ou seguro."},{"type":"h2","text":"Antes de colocar dinheiro: um roteiro de cuidados"},{"type":"ol","items":["Entenda de onde vem o rendimento e quem paga por ele. Se não consegue explicar em duas frases, não entre.","Veja o histórico do protocolo: tempo de operação, valor total depositado e se já foi atacado. Projetos mais antigos e testados tendem a ser menos arriscados que os novos, embora nenhum seja isento de risco.","Confira se o contrato foi auditado, por quem, e se há uma conta com poder de alterar as regras ou de congelar fundos.","Acesse só pelo endereço oficial, digitado ou salvo por você, nunca por link de anúncio, mensagem ou e-mail.","Comece com um valor pequeno e que você aceita perder por inteiro.","Use uma carteira separada para DeFi, sem a maior parte do seu patrimônio.","Revogue as permissões de tokens que não usa mais.","Anote cada operação: elas podem ter efeito no Imposto de Renda."]},{"type":"h2","text":"E o Imposto de Renda?"},{"type":"p","text":"Trocar um token por outro, vender ou receber recompensas pode ser um fato tributável, e a forma de tratar cada caso em DeFi ainda tem pontos em discussão. Guarde o histórico das operações e, para valores relevantes, converse com um contador. Para os casos mais comuns de compra e venda, use a [calculadora de IR sobre cripto](/ferramentas/calculadora-ir)."},{"type":"h2","text":"Em resumo"},{"type":"p","text":"DeFi é uma tecnologia real e em uso, mas o rendimento sempre vem de algum risco ou de alguém que paga por ele. Quanto maior o percentual prometido, mais perguntas você deve fazer. Nada neste guia é recomendação de investimento: é um mapa para você entender o terreno antes de decidir se quer pisar nele. Veja também o [aviso de risco](/aviso-de-risco)."}]', 'Entenda o que é DeFi, de onde vêm os rendimentos de empréstimos, pools e staking e os riscos: falha de contrato, liquidação e perda impermanente.', 'o que é defi', '["DeFi","Rendimento","Riscos","Avançado"]', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
